def endpoint_descriptions(name: str) -> dict[str, str]:
    """Return reviewed translations; do not guess descriptions for unknown APIs."""
    if name in DESCRIPTIONS:
        de, en = DESCRIPTIONS[name]
        result = {"de": de, "en": en}
        if name in DESCRIPTIONS_FR:
            result["fr"] = DESCRIPTIONS_FR[name]
        return result
    for prefix in ("describe_", "validate_", "get_", "set_"):
        if name.startswith(prefix) and name[len(prefix):] in CONFIG_SUBJECTS:
            de, en = CONFIG_SUBJECTS[name[len(prefix):]]
            texts = {
                "get_": (
                    f"Lädt die gespeicherte Konfiguration für {de}. Die Abfrage ändert keine Einstellungen.",
                    f"Loads the saved configuration for {en}. This request does not change settings."),
                "describe_": (
                    f"Liefert das JSON-Schema für {de}: Felder, Datentypen und Validierungsregeln. Das Schema beschreibt die Struktur, nicht die aktuell gespeicherten Werte.",
                    f"Returns the JSON schema for {en}: fields, data types and validation rules. It describes the structure, not currently saved values."),
                "validate_": (
                    f"Prüft einen Konfigurationsentwurf für {de}, ohne ihn zu speichern oder anzuwenden. Validierungsfehler helfen, ungültige Felder vor dem Speichern zu korrigieren.",
                    f"Validates proposed configuration for {en} without saving or applying it. Validation errors help correct invalid fields before saving."),
                "set_": (
                    f"Prüft und speichert die Konfiguration für {de}. Aktivierte Regeln können anschließend den Betrieb beeinflussen; für eine reine Prüfung dient der validate-Endpunkt.",
                    f"Validates and saves configuration for {en}. Enabled rules may subsequently affect operation; use the validate endpoint for a check only."),
            }
            de, en = texts[prefix]
            subject = CONFIG_SUBJECTS_FR[name[len(prefix):]]
            french = {
                "get_": f"Charge la configuration enregistrée pour {subject}. Cette requête ne modifie aucun paramètre.",
                "describe_": f"Renvoie le schéma JSON pour {subject} : champs, types et règles de validation. Il décrit la structure, pas les valeurs enregistrées.",
                "validate_": f"Vérifie un projet de configuration pour {subject} sans l'enregistrer ni l'appliquer. Les erreurs de validation aident à corriger les champs invalides avant l'enregistrement.",
                "set_": f"Vérifie et enregistre la configuration pour {subject}. Les règles activées peuvent ensuite affecter le fonctionnement ; utilisez le point d'accès validate pour une vérification seule.",
            }
            return {"de": de, "en": en, "fr": french[prefix]}
    return {}


def describe_api_endpoints(entries: list[dict]) -> list[dict]:
    """Enrich without altering methods, permissions, arguments or source docs."""
    return [
        {**entry, "description_translations": endpoint_descriptions(entry["endpoint"])}
        for entry in entries
    ]
